content:
@layer components {
  .card__title {
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-fgColor-default);
  }
}

@layer components {
  .card-title {
    font-size: var(--shelf-font-size-md);
    font-weight: var(--shelf-font-weight-semibold);
    color: var(--shelf-fgColor-default);
  }

  .card-author {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-fgColor-muted);
  }
}

@layer components {
  .card--skeleton {
    background-color: var(--shelf-bgColor-raised);
    border-radius: var(--shelf-radius-md);
    animation-name: shimmer;
  }
}

@layer tokens {
  :root {
    --shelf-bgColor-default: hsl(30 15% 97%);
  }
}

.token__debug {
  display: none;
}

@layer base {
  *, *::before, *::after { box-sizing: border-box; }
  body {
    margin: 0;
    background-color: var(--shelf-bgColor-default);
    color: var(--shelf-fgColor-default);
    font-family: var(--shelf-font-family-base);
  }
}

@layer components {
  .chip-bar {
    display: flex;
    gap: var(--shelf-space-sm);
    padding: var(--shelf-space-sm) var(--shelf-space-md);
  }

  .chip-label {
    font-size: var(--shelf-font-size-sm);
    color: var(--shelf-fgColor-default);
  }
}

@layer components {
  .drawer {
    position: fixed;
    inset-block: 0;
    background-color: var(--shelf-bgColor-raised);
  }

  .drawer-header {
    display: flex;
    align-items: center;
    padding: var(--shelf-space-md);
  }

  .drawer-body {
    padding: var(--shelf-space-md);
    overflow-y: auto;
  }

  .drawer-backdrop {
    position: fixed;
    inset: 0;
    background-color: var(--shelf-bgColor-overlay);
  }
}
